import torch

def gen_inputs(ctx, device):
    m, k = ctx['compressed_A__shape']
    n = ctx['dense_B__shape'][1]
    dtype = getattr(torch, ctx['compressed_A__dtype'])
    a = torch.randn(m, k, dtype=dtype, device=device)
    b = torch.randn(k, n, dtype=dtype, device=device)
    compressed_a = torch.ops.aten._cslt_compress(a)
    return {'compressed_A': compressed_a, 'dense_B': b}

def run(compressed_A, dense_B):
    return torch.ops.aten._cslt_sparse_mm(compressed_A, dense_B)
